cases.sql:
SELECT id, shipping_fee, status, order_date
FROM orders
WHERE customer_id IN (SELECT id FROM customers WHERE country = 'TH');

select id, order_id, carrier
from shipments
where order_id is not null and order_id not in (select id from orders);

select id, supplier_id, category, brand
from products
where supplier_id not in (select id from suppliers) and supplier_id is not null;

SELECT id, txn_time, txn_type, merchant
FROM transactions
WHERE account_id IN (SELECT id FROM accounts WHERE balance < 57456.1);

select id, order_id, paid_at, status, amount
from payments
where order_id in (select id from orders where shipping_fee < 33.8);

select id, store_id, quantity, last_restock
from inventory
where store_id not in (select id from stores where city <> 'London');

select id, discount
from orders
where id in (select order_id from payments);
